const {recordId} = input.config();
const table = base.getTable('Campaigns');
const record = await table.selectRecordAsync(recordId);
if (!record) throw new Error('Campaign record not found.');

const payload = Object.fromEntries(
    table.fields.map(field => [field.name, record.getCellValue(field)])
);
payload.recordId = record.id;

const response = await fetch('https://n8n.dulcy.io/webhook/REDACTED_PATH', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload),
});

if (!response.ok) {
    const message = await response.text();
    throw new Error(`EmailBison action failed (${response.status}): ${message}`);
}
